import itertools
import random

def get_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for i in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    min_cycle = min(min_cycle, dist[u] + dist[v] + 1)
    return min_cycle

def is_4_colorable(n, adj):
    colors = [-1] * n
    def can_color(u):
        if u == n: return True
        for c in range(4):
            safe = True
            for v in adj[u]:
                if colors[v] == c:
                    safe = False
                    break
            if safe:
                colors[u] = c
                if can_color(u + 1): return True
                colors[u] = -1
        return False
    return can_color(0)

def solve():
    n = 14
    # Try to build the graph by adding edges one by one
    # and maintaining girth >= 6

    for _ in range(1000):
        edges = []
        adj = [[] for _ in range(n)]

        possible_edges = list(itertools.combinations(range(n), 2))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            # Check if adding (u, v) creates a cycle of length < 6
            # A cycle of length < 6 is a cycle of length 3, 4, or 5.
            # This is equivalent to saying there is a path of length 1, 2, 3, or 4 between u and v.
            # Path of length 1: (u, v) exists (not possible here)
            # Path of length 2: u - w - v
            # Path of length 3: u - w1 - w2 - v
            # Path of length 4: u - w1 - w2 - w3 - v

            # Check for path of length 2:
            path2 = False
            for w in range(n):
                if w in adj[u] and w in adj[v]:
                    path2 = True
                    break
            if path2: continue

            # Check for path of length 3:
            path3 = False
            for w1 in adj[u]:
                for w2 in adj[v]:
                    if w1 == w2: continue # This would be path of length 2
                    if w2 in adj[w1]:
                        path3 = True
                        break
                if path3: break
            if path3: continue

            # Check for path of length 4:
            path4 = False
            for w1 in adj[u]:
                for w2 in range(n):
                    if w2 == u or w2 == v or w2 == w1: continue
                    if w2 in adj[w1]:
                        for w3 in adj[w2]:
                            if w3 == w1 or w3 == u or w3 == v: continue
                            if w3 in adj[v]:
                                path4 = True
                                break
                    if path4: break
                if path4: break
            if path4: continue

            edges.append((u, v))
            adj[u].append(v)
            adj[v].append(u)

            if len(edges) == 26:
                if is_4_colorable(n, adj):
                    return edges
    return None

result = solve()
